BEGIN;
-- PT112-S3-Q25
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND q.stimulus=$batch01$Anthropologist: All music is based on a few main systems of scale building. Clearly, if the popularity of a musical scale were a result of social conditioning, we would expect, given the diversity of social systems, a diverse mixture of diatonic and nondiatonic scales in the world’s music. Yet diatonic scales have always dominated the music of most of the world. Therefore, the popularity of diatonic music can be attributed only to innate dispositions of the human mind.$batch01$ AND q.prompt=$batch01$The anthropologist's argument is most vulnerable to criticism on the grounds that it fails to$batch01$ AND q.correct_choice=$batch01$D$batch01$) THEN RAISE EXCEPTION 'Question changed: PT112-S3-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S3-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$consider the possibility that some people appreciate nondiatonic music more than they do diatonic music$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S3-Q25 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$explain how innate dispositions increase appreciation of nondiatonic music$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S3-Q25 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$explain the existence of diatonic scales as well as the existence of nondiatonic scales$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S3-Q25 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$consider that innate dispositions and social conditioning could jointly affect the popularity of a type of music$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S3-Q25 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$consider whether any appreciation of nondiatonic music is demonstrated by some nonhuman species of animals$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S3-Q25 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT112-S3-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Diatonic music's popularity can be attributed *only* to innate dispositions of the human mind.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$If social conditioning caused a scale's popularity, the anthropologist expects varied social systems to yield a varied mixture of scales. Instead, diatonic scales dominate much of the world's music.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Even if a purely social explanation were inadequate, why must innate disposition act alone? Similar human dispositions could make diatonic music appealing, while social learning reinforces and spreads it. Ruling out one proposed explanation as complete does not rule out a combined explanation.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the unjustified either-or: innate influence and social conditioning can both contribute.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Some people could prefer nondiatonic music while diatonic scales still dominate most music. Individual exceptions do not address whether social conditioning contributes to the broad pattern.$batch01$), ($batch01$B$batch01$, $batch01$The conclusion explains diatonic music's popularity, not how innate dispositions affect appreciation of nondiatonic music.$batch01$), ($batch01$C$batch01$, $batch01$A theory of why diatonic scales are popular need not explain the existence of every scale. The argument's issue is the exclusivity of the proposed cause.$batch01$), ($batch01$D$batch01$, $batch01$Innate dispositions and social conditioning might jointly influence popularity. The failure of the anthropologist's prediction for a *purely* social explanation does not show that social conditioning contributes nothing.$batch01$), ($batch01$E$batch01$, $batch01$The argument concerns patterns in human music and the human mind. Animal appreciation of nondiatonic music would not settle whether social conditioning helps explain human preference for diatonic scales.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT112-S3-Q25$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
